"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[7858],{7908(s,n,e){e.r(n),e.d(n,{assets:()=>p,contentTitle:()=>c,default:()=>u,frontMatter:()=>l,metadata:()=>a,toc:()=>d});const a=JSON.parse('{"id":"part3-agent-protocols/mcp-discovery-remote-auth","title":"MCP Discovery, Remote Transport, and Authentication","description":"This chapter connects MCP basics (resources, prompts, tools) to server/client code, how remote MCP servers are used by LLMs (OpenAI-style analogy), and how authentication fits in (self-hosted Identity Provider, Bearer...","source":"@site/docs/part3-agent-protocols/02-mcp-discovery-remote-auth.mdx","sourceDirName":"part3-agent-protocols","slug":"/part3-agent-protocols/02-mcp-discovery-remote-auth","permalink":"/tutorials/part3-agent-protocols/02-mcp-discovery-remote-auth","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":2,"frontMatter":{"title":"MCP Discovery, Remote Transport, and Authentication","slug":"/part3-agent-protocols/02-mcp-discovery-remote-auth","description":"This chapter connects MCP basics (resources, prompts, tools) to server/client code, how remote MCP servers are used by LLMs (OpenAI-style analogy), and how authentication fits in (self-hosted Identity Provider, Bearer...","sidebar_label":"2. MCP discovery, remote transport, and auth","pagination_label":"2. MCP discovery, remote transport, and auth","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"1. MCP fundamentals","permalink":"/tutorials/part3-agent-protocols/01-mcp-fundamentals"},"next":{"title":"3. MCP enterprise pattern","permalink":"/tutorials/part3-agent-protocols/03-mcp-enterprise-pattern"}}');var t=e(4848),o=e(8453),r=e(8172);const i=JSON.parse('{"sourcePath":"part3-agent-protocols/02-mcp-discovery-remote-auth.html","route":"/part3-agent-protocols/02-mcp-discovery-remote-auth","kind":"chapter","partId":"part3","partLabel":"Part III - Agent Protocols & Integration","accent":"violet","heading":"MCP Discovery, Remote Transport, and Authentication","title":"MCP Discovery, Remote Transport, and Authentication","description":"This chapter connects MCP basics (resources, prompts, tools) to server/client code, how remote MCP servers are used by LLMs (OpenAI-style analogy), and how authentication fits in (self-hosted Identity Provider, Bearer...","readingMinutes":13,"bodyClass":"","normalizeMath":false,"toc":[{"id":"1-what-mcp-is-and-what-it-isn-t","label":"1) What MCP is (and what it isn\u2019t)"},{"id":"2-core-mcp-components-resources-prompts-tools","label":"2) Core MCP components: resources, prompts, tools"},{"id":"3-discovery-how-a-client-finds-resources-prompts-tools","label":"3) Discovery: how a client finds resources/prompts/tools"},{"id":"4-server-tutorial-a-simple-mcp-shop-server-in-python","label":"4) Server tutorial: a simple MCP \u201cshop\u201d server in Python"},{"id":"5-client-tutorial-list-resources-prompts-tools-and-call-them","label":"5) Client tutorial: list resources/prompts/tools and call them"},{"id":"6-remote-mcp-servers-and-the-mcp-shop-analogy","label":"6) Remote MCP servers and the \u201cmcp.shop\u201d analogy"},{"id":"7-using-a-remote-mcp-server-from-an-llm-openai-analogy","label":"7) Using a remote MCP server from an LLM (OpenAI analogy)"},{"id":"8-authentication-and-identity-providers-in-mcp","label":"8) Authentication & Identity Providers in MCP"},{"id":"9-self-hosted-idp-bearer-token-middleware-validation","label":"9) Self-hosted IdP + Bearer token + middleware validation"},{"id":"10-how-clients-get-tokens-pkce-client-credentials-and-token-exchange","label":"10) How clients get tokens: PKCE, client credentials, and token exchange"},{"id":"11-server-validation-introspection-vs-jwks-public-key-retrieval-at-start","label":"11) Server validation: introspection vs JWKS (public key retrieval at start)"},{"id":"12-best-practices-and-troubleshooting","label":"12) Best practices & troubleshooting"},{"id":"final-end-to-end-picture","label":"Final end-to-end picture"},{"id":"official-references","label":"Official references"}],"html":"<header>\\n  <div class=\\"wrap\\">\\n    \\n    <p class=\\"muted\\">\\n      This chapter connects MCP basics (resources, prompts, tools) to server/client code,\\n      how remote MCP servers are used by LLMs (OpenAI-style analogy),\\n      and how authentication fits in (self-hosted Identity Provider, Bearer tokens, PKCE, introspection vs JWKS).\\n    </p>\\n\\n    <div class=\\"tr-note\\">\\n      <strong>Reading path</strong>\\n      This is the primary MCP technical chapter. <a href=\\"/tutorials/part3-agent-protocols/01-mcp-fundamentals\\">Chapter 1</a>\\n      is the beginner local example, <a href=\\"/tutorials/part3-agent-protocols/03-mcp-enterprise-pattern\\">Chapter 3</a>\\n      is the enterprise application, and <a href=\\"/tutorials/part3-agent-protocols/04-mcp-2025-update\\">Chapter 4</a>\\n      explains the protocol\'s 2025-to-2026 evolution. For OAuth/OIDC/JWT theory, use\\n      <a href=\\"/tutorials/part2-backend-platform-security/09-authentication-deep-dive\\">Part II Chapter 10</a>.\\n    </div>\\n\\n    <div class=\\"tr-update\\">\\n      <strong>Current protocol versus compatibility SDKs</strong>\\n      The normative protocol in this chapter is MCP\\n      <code>2026-07-28</code>. It uses stateless, self-contained requests,\\n      optional up-front <code>server/discover</code>, and per-request\\n      <code>_meta</code>. The explicit <code>ClientSession.initialize()</code>\\n      example later in the chapter is retained and labelled as the older\\n      2025-compatible Python SDK shape because deployed clients and adapters\\n      may still negotiate that version.\\n    </div>\\n\\n    <div class=\\"toc\\">\\n      <strong>Table of contents</strong>\\n      <ul>\\n        <li><a href=\\"#what-is-mcp\\">1) What MCP is (and what it isn\u2019t)</a></li>\\n        <li><a href=\\"#core-components\\">2) Core MCP components: resources, prompts, tools</a></li>\\n        <li><a href=\\"#discovery\\">3) Discovery: how a client finds resources/prompts/tools</a></li>\\n        <li><a href=\\"#local-server\\">4) Server tutorial: a simple MCP \u201cshop\u201d server in Python</a></li>\\n        <li><a href=\\"#local-client\\">5) Client tutorial: list resources/prompts/tools and call them</a></li>\\n        <li><a href=\\"#remote-server\\">6) Remote MCP servers and \u201cmcp.shop\u201d style analogy</a></li>\\n        <li><a href=\\"#openai-llm\\">7) Using a remote MCP server from an LLM (OpenAI analogy)</a></li>\\n        <li><a href=\\"#auth\\">8) Authentication &amp; Identity Providers in MCP</a></li>\\n        <li><a href=\\"#auth-selfhosted\\">9) Self-hosted IdP + Bearer token + middleware validation</a></li>\\n        <li><a href=\\"#auth-get-token\\">10) How the client gets tokens (PKCE, client credentials, token exchange)</a></li>\\n        <li><a href=\\"#auth-validate\\">11) How the server validates tokens (introspection vs JWKS)</a></li>\\n        <li><a href=\\"#best-practices\\">12) Practical best practices (tool allow-list, least privilege, CORS)</a></li>\\n        <li><a href=\\"#troubleshooting\\">12) Best practices and troubleshooting</a></li>\\n      </ul>\\n    </div>\\n  </div>\\n</header>\\n\\n<main class=\\"wrap\\">\\n\\n  <section id=\\"what-is-mcp\\">\\n    <h2 id=\\"1-what-mcp-is-and-what-it-isn-t\\">1) What MCP is (and what it isn\u2019t)</h2>\\n\\n    <p>\\n      MCP (Model Context Protocol) is a standard interface for connecting an AI host (the app that runs the model)\\n      to external capabilities offered by servers. Those capabilities usually fall into three buckets:\\n      <span class=\\"badge\\">Resources</span><span class=\\"badge\\">Prompts</span><span class=\\"badge\\">Tools</span>.\\n    </p>\\n\\n    <div class=\\"card\\">\\n      <div class=\\"diagram\\">\\n        User \u2194 Host App (LLM) \u2194 MCP Server(s)\\n      </div>\\n      <p class=\\"muted\\">\\n        The host app is in control: it decides what context to provide to the LLM and which tools the LLM is allowed to call.\\n        The MCP server is \u201cjust\u201d a capability provider.\\n      </p>\\n    </div>\\n\\n    <div class=\\"callout warn\\">\\n      <strong>Important:</strong> MCP is not \u201cthe LLM calling the Internet by itself.\u201d\\n      In well-designed systems, the LLM proposes actions, but the host executes calls and enforces policy.\\n      That is exactly how you keep things safe and predictable.\\n    </div>\\n\\n    <h3 id=\\"1-1-beginner-mental-model-the-3-roles\\">1.1 Beginner mental model (the 3 roles)</h3>\\n    <div class=\\"card\\">\\n      <div class=\\"diagram\\">\\n        (1) User asks a question\\n          \u2193\\n        (2) Host app (your code) decides what to do\\n          \u2193\\n        (3) Host talks to MCP server(s) for data/actions\\n          \u2193\\n        (4) Host feeds results back to the LLM and the user\\n      </div>\\n      <p class=\\"muted\\">\\n        Beginners often think \u201cthe model calls the tool\u201d. In reality, the <strong>host</strong> is the component that\\n        makes network calls and enforces policy (allow-lists, rate limits, auth headers).\\n      </p>\\n    </div>\\n\\n    <h3 id=\\"1-2-key-mcp-terms-quick-glossary\\">1.2 Key MCP terms (quick glossary)</h3>\\n    <table>\\n      <thead>\\n        <tr>\\n          <th>Term</th>\\n          <th>Beginner explanation</th>\\n          <th>Example</th>\\n        </tr>\\n      </thead>\\n      <tbody>\\n        <tr>\\n          <td><strong>Host</strong></td>\\n          <td>Your app that runs the LLM and enforces policy.</td>\\n          <td>A Python service using an LLM SDK.</td>\\n        </tr>\\n        <tr>\\n          <td><strong>MCP Server</strong></td>\\n          <td>A capability provider that exposes resources/prompts/tools.</td>\\n          <td>A \u201cshop\u201d server exposing <code class=\\"inline\\">inventory_check</code>.</td>\\n        </tr>\\n        <tr>\\n          <td><strong>Transport</strong></td>\\n          <td>How messages move between host and server (stdio or HTTP).</td>\\n          <td>Streamable HTTP at <code class=\\"inline\\">/mcp</code>.</td>\\n        </tr>\\n        <tr>\\n          <td><strong>Discovery</strong></td>\\n          <td>Listing what exists (tools/resources/prompts) before using them.</td>\\n          <td><code class=\\"inline\\">list_tools()</code> then <code class=\\"inline\\">call_tool()</code>.</td>\\n        </tr>\\n        <tr>\\n          <td><strong>Stateless vs stateful</strong></td>\\n          <td>Whether the server expects a durable session per client.</td>\\n          <td>Stateless HTTP is simplest to scale.</td>\\n        </tr>\\n      </tbody>\\n    </table>\\n  </section>\\n\\n  <section id=\\"core-components\\">\\n    <h2 id=\\"2-core-mcp-components-resources-prompts-tools\\">2) Core MCP components: resources, prompts, tools</h2>\\n\\n    <p>\\n      Here\u2019s a conceptual mapping that makes MCP intuitive:\\n    </p>\\n\\n    <table>\\n      <thead>\\n        <tr>\\n          <th>Component</th>\\n          <th>What it is</th>\\n          <th>What the host typically does with it</th>\\n          <th>Example in a \u201cshop\u201d domain</th>\\n        </tr>\\n      </thead>\\n      <tbody>\\n        <tr>\\n          <td><strong>Resources</strong></td>\\n          <td>Named/URI-addressed context objects (data you want the model to read).</td>\\n          <td>Fetch and inject into the LLM\u2019s context (or summarize first).</td>\\n          <td><code class=\\"inline\\">shop://catalog</code>, <code class=\\"inline\\">shop://schema</code></td>\\n        </tr>\\n        <tr>\\n          <td><strong>Prompts</strong></td>\\n          <td>Reusable prompt templates or workflows published by the server.</td>\\n          <td>Present to user or internally use as standard instructions.</td>\\n          <td>\u201cWrite a purchase summary for SKU + quantity\u201d</td>\\n        </tr>\\n        <tr>\\n          <td><strong>Tools</strong></td>\\n          <td>Callable functions with structured inputs/outputs. Can have side effects.</td>\\n          <td>Allow the model to call them (with restrictions), then return results back to the model.</td>\\n          <td><code class=\\"inline\\">inventory_check(sku, qty)</code>, <code class=\\"inline\\">create_order(sku, qty)</code></td>\\n        </tr>\\n      </tbody>\\n    </table>\\n\\n    <div class=\\"callout ok\\">\\n      <strong>Quick rule:</strong>\\n      If something is read-only or \u201ccontext,\u201d make it a Resource. If it\u2019s a reusable instruction, make it a Prompt.\\n      If it changes state (writes, creates, sends), make it a Tool.\\n    </div>\\n  </section>\\n\\n  <section id=\\"discovery\\">\\n    <h2 id=\\"3-discovery-how-a-client-finds-resources-prompts-tools\\">3) Discovery: how a client finds resources/prompts/tools</h2>\\n\\n    <p>\\n      Discovery is the step that confused you earlier (\u201cwhere is mcp_call? how does discovery happen?\u201d).\\n      The answer is: the host connects to the server and asks for the catalogs.\\n    </p>\\n\\n    <div class=\\"card\\">\\n      <strong>Typical host flow (high-level):</strong>\\n      <ol>\\n        <li>Connect to MCP server transport (stdio, local HTTP, remote HTTP)</li>\\n        <li>Discover/select the protocol version, or let a compatible SDK negotiate it</li>\\n        <li>List tools (names + input and optional output schema)</li>\\n        <li>List prompts (names + args)</li>\\n        <li>List resources (URIs + metadata)</li>\\n      </ol>\\n    </div>\\n\\n    <p>\\n      After discovery, the host can do two important policy steps:\\n    </p>\\n    <ul>\\n      <li><strong>Tool allow-list</strong>: choose which tools the model may call (e.g., only read-only tools in production).</li>\\n      <li><strong>Context selection</strong>: decide which resources to inject (to avoid over-sharing or prompt bloat).</li>\\n    </ul>\\n\\n    <div class=\\"callout warn\\">\\n      Discovery doesn\u2019t mean the model automatically sees everything.\\n      The host chooses what to show and what to enable.\\n    </div>\\n\\n    <h3 id=\\"3-1-transports-how-mcp-messages-travel\\">3.1 Transports (how MCP messages travel)</h3>\\n    <p>\\n      MCP is a protocol. It can be carried over different transports.\\n      Beginners usually start with <strong>Streamable HTTP</strong> (easy to deploy) or <strong>stdio</strong> (great for local tools).\\n    </p>\\n    <div class=\\"card\\">\\n      <strong>Common transports:</strong>\\n      <ul>\\n        <li><strong>stdio</strong>: host spawns the server process and communicates via stdin/stdout (local only).</li>\\n        <li><strong>HTTP</strong>: server runs as a web app; host calls it over the network (local or remote).</li>\\n      </ul>\\n      <p class=\\"muted\\">\\n        Remote servers usually use HTTP because it works across machines and supports standard web controls (auth, rate limits, logs).\\n      </p>\\n    </div>\\n\\n    <h3 id=\\"3-2-version-discovery-current-protocol-and-historical-handshake\\">3.2 Version discovery: current protocol and historical handshake</h3>\\n    <p>\\n      In the 2025 protocol family, <code class=\\"inline\\">initialize()</code>\\n      was the handshake where client and server negotiated version and\\n      capabilities before normal calls. MCP <code>2026-07-28</code> removed\\n      that handshake and protocol-level sessions. A current server implements\\n      <code class=\\"inline\\">server/discover</code>; each ordinary request then\\n      carries its selected protocol version, client capabilities, and client\\n      identity in <code class=\\"inline\\">params._meta</code>. The request must be\\n      processable without remembering a previous connection.\\n    </p>\\n\\n    <h3 id=\\"3-3-tool-schemas-why-structured-inputs-matter\\">3.3 Tool schemas: why structured inputs matter</h3>\\n    <p>\\n      Tools are not \u201cfree-form strings\u201d. Each tool has a schema (think: a mini API contract).\\n      That lets the host validate inputs before calling and gives the LLM a clear structure to follow.\\n    </p>\\n    <div class=\\"callout ok\\">\\n      <strong>Beginner rule:</strong> If you can\u2019t describe a tool\u2019s inputs/outputs as JSON, the tool is probably too vague.\\n      Split it into smaller tools.\\n    </div>\\n  </section>\\n\\n  <div class=\\"hr\\"></div>\\n\\n  <section id=\\"local-server\\">\\n    <h2 id=\\"4-server-tutorial-a-simple-mcp-shop-server-in-python\\">4) Server tutorial: a simple MCP \u201cshop\u201d server in Python</h2>\\n\\n    <p>\\n      This server has:\\n      <strong>2 resources</strong> (catalog and schema),\\n      <strong>1 prompt</strong> (purchase summary prompt),\\n      and <strong>2 tools</strong> (inventory check and create order).\\n    </p>\\n\\n    <p class=\\"muted\\">\\n      This is a toy example but it demonstrates the full pattern: read context (resources), reuse instructions (prompt),\\n      perform actions (tools).\\n    </p>\\n\\n    <pre class=\\"code\\"><code><span class=\\"com\\"># server.py</span>\\n<span class=\\"kw\\">from</span> <span class=\\"typ\\">typing</span> <span class=\\"kw\\">import</span> <span class=\\"typ\\">TypedDict</span>, <span class=\\"typ\\">Optional</span>\\n<span class=\\"kw\\">from</span> <span class=\\"typ\\">mcp.server.fastmcp</span> <span class=\\"kw\\">import</span> <span class=\\"typ\\">FastMCP</span>\\n\\n<span class=\\"com\\"># Create the MCP server</span>\\nmcp <span class=\\"op\\">=</span> <span class=\\"typ\\">FastMCP</span>(\\n    <span class=\\"str\\">\\"MiniShop MCP\\"</span>,\\n    stateless_http<span class=\\"op\\">=</span><span class=\\"kw\\">True</span>,\\n    json_response<span class=\\"op\\">=</span><span class=\\"kw\\">True</span>,\\n)\\n\\n<span class=\\"com\\"># In-memory demo data</span>\\nCATALOG <span class=\\"op\\">=</span> {\\n  <span class=\\"str\\">\\"SKU-APPLE\\"</span>: {<span class=\\"str\\">\\"name\\"</span>: <span class=\\"str\\">\\"Apple\\"</span>, <span class=\\"str\\">\\"price\\"</span>: <span class=\\"num\\">1.50</span>, <span class=\\"str\\">\\"stock\\"</span>: <span class=\\"num\\">12</span>},\\n  <span class=\\"str\\">\\"SKU-CHAIR\\"</span>: {<span class=\\"str\\">\\"name\\"</span>: <span class=\\"str\\">\\"Chair\\"</span>, <span class=\\"str\\">\\"price\\"</span>: <span class=\\"num\\">49.00</span>, <span class=\\"str\\">\\"stock\\"</span>: <span class=\\"num\\">0</span>},\\n}\\n\\n<span class=\\"com\\"># ----------------------</span>\\n<span class=\\"com\\"># RESOURCES</span>\\n<span class=\\"com\\"># ----------------------</span>\\n@mcp.<span class=\\"fn\\">resource</span>(<span class=\\"str\\">\\"shop://catalog\\"</span>)\\n<span class=\\"kw\\">def</span> <span class=\\"fn\\">catalog_snapshot</span>() <span class=\\"op\\">-&gt;</span> <span class=\\"typ\\">str</span>:\\n    <span class=\\"kw\\">import</span> <span class=\\"typ\\">json</span>\\n    <span class=\\"kw\\">return</span> json.<span class=\\"fn\\">dumps</span>(CATALOG, indent<span class=\\"op\\">=</span><span class=\\"num\\">2</span>)\\n\\n@mcp.<span class=\\"fn\\">resource</span>(<span class=\\"str\\">\\"shop://schema\\"</span>)\\n<span class=\\"kw\\">def</span> <span class=\\"fn\\">schema_doc</span>() <span class=\\"op\\">-&gt;</span> <span class=\\"typ\\">str</span>:\\n    <span class=\\"kw\\">return</span> <span class=\\"str\\">\\"\\"\\"Data shapes:</span>\\n<span class=\\"str\\">- Catalog item: { name: string, price: number, stock: number }</span>\\n<span class=\\"str\\">- Order request: { sku: string, qty: number }</span>\\n<span class=\\"str\\">- Order result: { order_id: string, status: \'created\'|\'rejected\', reason?: string }</span>\\n<span class=\\"str\\">\\"\\"\\"</span>\\n\\n<span class=\\"com\\"># ----------------------</span>\\n<span class=\\"com\\"># PROMPTS</span>\\n<span class=\\"com\\"># ----------------------</span>\\n@mcp.<span class=\\"fn\\">prompt</span>(title<span class=\\"op\\">=</span><span class=\\"str\\">\\"Purchase Summary\\"</span>)\\n<span class=\\"kw\\">def</span> <span class=\\"fn\\">purchase_summary_prompt</span>(sku: <span class=\\"typ\\">str</span>, qty: <span class=\\"typ\\">int</span>) <span class=\\"op\\">-&gt;</span> <span class=\\"typ\\">str</span>:\\n    item <span class=\\"op\\">=</span> CATALOG.<span class=\\"fn\\">get</span>(sku)\\n    <span class=\\"kw\\">if</span> <span class=\\"kw\\">not</span> item:\\n        <span class=\\"kw\\">return</span> <span class=\\"str\\">f\\"Write a polite message: SKU {sku} does not exist.\\"</span>\\n    <span class=\\"kw\\">return</span> <span class=\\"str\\">f\\"\\"\\"Write a short purchase summary for the user.</span>\\n<span class=\\"str\\">Item: {item[\'name\']} ({sku})</span>\\n<span class=\\"str\\">Quantity: {qty}</span>\\n<span class=\\"str\\">Unit price: ${item[\'price\']}</span>\\n<span class=\\"str\\">Mention stock status and alternatives if stock is low/zero.</span>\\n<span class=\\"str\\">\\"\\"\\"</span>\\n\\n<span class=\\"com\\"># ----------------------</span>\\n<span class=\\"com\\"># TOOLS</span>\\n<span class=\\"com\\"># ----------------------</span>\\n<span class=\\"kw\\">class</span> <span class=\\"typ\\">InventoryResult</span>(<span class=\\"typ\\">TypedDict</span>):\\n    sku: <span class=\\"typ\\">str</span>\\n    requested: <span class=\\"typ\\">int</span>\\n    available: <span class=\\"typ\\">int</span>\\n    can_fulfill: <span class=\\"typ\\">bool</span>\\n\\n@mcp.<span class=\\"fn\\">tool</span>()\\n<span class=\\"kw\\">def</span> <span class=\\"fn\\">inventory_check</span>(sku: <span class=\\"typ\\">str</span>, qty: <span class=\\"typ\\">int</span>) <span class=\\"op\\">-&gt;</span> <span class=\\"typ\\">InventoryResult</span>:\\n    item <span class=\\"op\\">=</span> CATALOG.<span class=\\"fn\\">get</span>(sku, {<span class=\\"str\\">\\"stock\\"</span>: <span class=\\"num\\">0</span>})\\n    available <span class=\\"op\\">=</span> <span class=\\"typ\\">int</span>(item[<span class=\\"str\\">\\"stock\\"</span>])\\n    <span class=\\"kw\\">return</span> {\\n        <span class=\\"str\\">\\"sku\\"</span>: sku,\\n        <span class=\\"str\\">\\"requested\\"</span>: qty,\\n        <span class=\\"str\\">\\"available\\"</span>: available,\\n        <span class=\\"str\\">\\"can_fulfill\\"</span>: available <span class=\\"op\\">&gt;=</span> qty,\\n    }\\n\\n<span class=\\"kw\\">class</span> <span class=\\"typ\\">OrderResult</span>(<span class=\\"typ\\">TypedDict</span>, total<span class=\\"op\\">=</span><span class=\\"kw\\">False</span>):\\n    order_id: <span class=\\"typ\\">str</span>\\n    status: <span class=\\"typ\\">str</span>     <span class=\\"com\\"># \\"created\\" | \\"rejected\\"</span>\\n    reason: <span class=\\"typ\\">Optional</span>[<span class=\\"typ\\">str</span>]\\n\\n@mcp.<span class=\\"fn\\">tool</span>()\\n<span class=\\"kw\\">def</span> <span class=\\"fn\\">create_order</span>(sku: <span class=\\"typ\\">str</span>, qty: <span class=\\"typ\\">int</span>) <span class=\\"op\\">-&gt;</span> <span class=\\"typ\\">OrderResult</span>:\\n    check <span class=\\"op\\">=</span> inventory_check(sku, qty)\\n    <span class=\\"kw\\">if</span> <span class=\\"kw\\">not</span> check[<span class=\\"str\\">\\"can_fulfill\\"</span>]:\\n        <span class=\\"kw\\">return</span> {<span class=\\"str\\">\\"status\\"</span>: <span class=\\"str\\">\\"rejected\\"</span>, <span class=\\"str\\">\\"reason\\"</span>: <span class=\\"str\\">\\"Insufficient stock\\"</span>}\\n    <span class=\\"com\\"># Side effect: reserve stock</span>\\n    CATALOG[sku][<span class=\\"str\\">\\"stock\\"</span>] <span class=\\"op\\">-=</span> qty\\n    <span class=\\"kw\\">import</span> <span class=\\"typ\\">uuid</span>\\n    <span class=\\"kw\\">return</span> {<span class=\\"str\\">\\"status\\"</span>: <span class=\\"str\\">\\"created\\"</span>, <span class=\\"str\\">\\"order_id\\"</span>: <span class=\\"str\\">f\\"ord_{uuid.uuid4().hex[:8]}\\"</span>}\\n\\n<span class=\\"com\\"># ----------------------</span>\\n<span class=\\"com\\"># Expose as a Streamable HTTP MCP app</span>\\n<span class=\\"com\\"># ----------------------</span>\\napp <span class=\\"op\\">=</span> mcp.<span class=\\"fn\\">streamable_http_app</span>()\\n\\n<span class=\\"com\\"># Run with: uvicorn server:app --host 127.0.0.1 --port 8000</span></code></pre>\\n\\n    <div class=\\"card\\">\\n      <strong>What you just built</strong>\\n      <ul>\\n        <li>Resources are readable by URI (catalog/schema)</li>\\n        <li>Prompt provides a reusable instruction template</li>\\n        <li>Tools enable actions (inventory check, create order)</li>\\n      </ul>\\n      <p class=\\"muted\\">\\n        In a real deployment, your resources might be \u201cdatabase schema\u201d, \u201clatest sales report\u201d, \u201ccustomer profile\u201d.\\n        Tools might be \u201crun SQL\u201d, \u201ccreate ticket\u201d, \u201capprove order\u201d.\\n      </p>\\n    </div>\\n  </section>\\n\\n  <section id=\\"local-client\\">\\n    <h2 id=\\"5-client-tutorial-list-resources-prompts-tools-and-call-them\\">5) Client tutorial: list resources/prompts/tools and call them</h2>\\n\\n    <p>\\n      The client is the \u201chost brain\u201d that:\\n      (1) discovers what the server provides, and then\\n      (2) reads resources or calls tools.\\n    </p>\\n\\n    <p class=\\"muted\\">\\n      This client uses MCP\u2019s streamable HTTP client transport.\\n      You can adapt the same pattern for stdio or other supported transports.\\n    </p>\\n\\n    <div class=\\"callout warn\\">\\n      <strong>Compatibility example:</strong> the code below is the\\n      stateful-looking Python SDK interface used with the 2025 protocol family.\\n      Its <code>initialize()</code> call is not part of the\\n      <code>2026-07-28</code> wire protocol. Do not infer that a current server\\n      may keep hidden per-client state. Use an SDK release that explicitly\\n      supports the protocol version selected by your server; do not delete\\n      this example if you maintain older deployments.\\n    </div>\\n\\n    <pre class=\\"code\\"><code><span class=\\"com\\"># client.py</span>\\n<span class=\\"kw\\">import</span> <span class=\\"typ\\">asyncio</span>\\n<span class=\\"kw\\">from</span> <span class=\\"typ\\">mcp.client.session</span> <span class=\\"kw\\">import</span> <span class=\\"typ\\">ClientSession</span>\\n<span class=\\"kw\\">from</span> <span class=\\"typ\\">mcp.client.streamable_http</span> <span class=\\"kw\\">import</span> <span class=\\"typ\\">streamable_http_client</span>\\n\\nMCP_URL <span class=\\"op\\">=</span> <span class=\\"str\\">\\"http://127.0.0.1:8000/mcp\\"</span>\\n\\n<span class=\\"kw\\">async def</span> <span class=\\"fn\\">main</span>():\\n    <span class=\\"kw\\">async with</span> streamable_http_client(MCP_URL) <span class=\\"kw\\">as</span> (read, write):\\n        <span class=\\"kw\\">async with</span> <span class=\\"typ\\">ClientSession</span>(read, write) <span class=\\"kw\\">as</span> session:\\n            <span class=\\"kw\\">await</span> session.<span class=\\"fn\\">initialize</span>()\\n\\n            <span class=\\"com\\"># 1) Discover tools</span>\\n            tools <span class=\\"op\\">=</span> <span class=\\"kw\\">await</span> session.<span class=\\"fn\\">list_tools</span>()\\n            <span class=\\"kw\\">print</span>(<span class=\\"str\\">\\"\\\\nTOOLS:\\"</span>)\\n            <span class=\\"kw\\">for</span> t <span class=\\"kw\\">in</span> tools:\\n                <span class=\\"kw\\">print</span>(<span class=\\"str\\">\\"-\\"</span>, t.name, <span class=\\"str\\">\\":\\"</span>, t.description)\\n\\n            <span class=\\"com\\"># 2) Discover resources</span>\\n            resources <span class=\\"op\\">=</span> <span class=\\"kw\\">await</span> session.<span class=\\"fn\\">list_resources</span>()\\n            <span class=\\"kw\\">print</span>(<span class=\\"str\\">\\"\\\\nRESOURCES:\\"</span>)\\n            <span class=\\"kw\\">for</span> r <span class=\\"kw\\">in</span> resources:\\n                <span class=\\"kw\\">print</span>(<span class=\\"str\\">\\"-\\"</span>, r.uri)\\n\\n            <span class=\\"com\\"># 3) Read a resource</span>\\n            catalog <span class=\\"op\\">=</span> <span class=\\"kw\\">await</span> session.<span class=\\"fn\\">read_resource</span>(<span class=\\"str\\">\\"shop://catalog\\"</span>)\\n            <span class=\\"kw\\">print</span>(<span class=\\"str\\">\\"\\\\nCATALOG RESOURCE CONTENT:\\\\n\\"</span>, catalog.contents[<span class=\\"num\\">0</span>].text)\\n\\n            <span class=\\"com\\"># 4) Discover prompts</span>\\n            prompts <span class=\\"op\\">=</span> <span class=\\"kw\\">await</span> session.<span class=\\"fn\\">list_prompts</span>()\\n            <span class=\\"kw\\">print</span>(<span class=\\"str\\">\\"\\\\nPROMPTS:\\"</span>)\\n            <span class=\\"kw\\">for</span> p <span class=\\"kw\\">in</span> prompts:\\n                <span class=\\"kw\\">print</span>(<span class=\\"str\\">\\"-\\"</span>, p.name)\\n\\n            <span class=\\"com\\"># 5) Call tools</span>\\n            inv <span class=\\"op\\">=</span> <span class=\\"kw\\">await</span> session.<span class=\\"fn\\">call_tool</span>(<span class=\\"str\\">\\"inventory_check\\"</span>, {<span class=\\"str\\">\\"sku\\"</span>: <span class=\\"str\\">\\"SKU-APPLE\\"</span>, <span class=\\"str\\">\\"qty\\"</span>: <span class=\\"num\\">2</span>})\\n            <span class=\\"kw\\">print</span>(<span class=\\"str\\">\\"\\\\nINVENTORY CHECK RESULT:\\\\n\\"</span>, inv.content[<span class=\\"num\\">0</span>].text)\\n\\n            order <span class=\\"op\\">=</span> <span class=\\"kw\\">await</span> session.<span class=\\"fn\\">call_tool</span>(<span class=\\"str\\">\\"create_order\\"</span>, {<span class=\\"str\\">\\"sku\\"</span>: <span class=\\"str\\">\\"SKU-APPLE\\"</span>, <span class=\\"str\\">\\"qty\\"</span>: <span class=\\"num\\">2</span>})\\n            <span class=\\"kw\\">print</span>(<span class=\\"str\\">\\"\\\\nCREATE ORDER RESULT:\\\\n\\"</span>, order.content[<span class=\\"num\\">0</span>].text)\\n\\n      <span class=\\"kw\\">if</span> __name__ <span class=\\"op\\">==</span> <span class=\\"str\\">\\"__main__\\"</span>:\\n        <span class=\\"typ\\">asyncio</span>.<span class=\\"fn\\">run</span>(main())</code></pre>\\n\\n    <div class=\\"card\\">\\n      <strong>How to run the client</strong>\\n      <pre class=\\"code\\"><code><span class=\\"com\\"># In another terminal (server already running):</span>\\npython client.py</code></pre>\\n      <p class=\\"muted\\">\\n        You should see the discovered TOOLS/RESOURCES/PROMPTS, the catalog resource content, and the JSON-ish tool results.\\n      </p>\\n    </div>\\n\\n    <h3 id=\\"what-you-should-notice-in-this-client\\">What you should notice in this client</h3>\\n    <ul>\\n      <li><strong>Discovery</strong> is explicit: you call <code class=\\"inline\\">list_tools</code>, <code class=\\"inline\\">list_resources</code>, <code class=\\"inline\\">list_prompts</code>.</li>\\n      <li><strong>Resources</strong> are read with <code class=\\"inline\\">read_resource(uri)</code> and returned as content blocks.</li>\\n      <li><strong>Tools</strong> are invoked with <code class=\\"inline\\">call_tool(name, args_dict)</code>.</li>\\n      <li><strong>Prompts</strong> appear in discovery; many hosts surface them to users as \u201crecipes\u201d.</li>\\n    </ul>\\n\\n    <div class=\\"callout ok\\">\\n      <strong>Connection to what we discussed earlier:</strong><br>\\n      This is the MCP equivalent of \u201cpassing dictionaries\u201d in LangChain: tool calls are structured dict inputs,\\n      and tool results become structured outputs that the host can feed back to the LLM.\\n    </div>\\n\\n    <div class=\\"tr-update\\">\\n      <strong>The same client flow on MCP 2026-07-28</strong>\\n      The host may call <code>server/discover</code>, selects a mutually\\n      supported version, and sends <code>tools/list</code>,\\n      <code>resources/list</code>, <code>prompts/list</code>, and later calls\\n      as independent requests. Each request repeats protocol and capability\\n      metadata. Application continuity uses explicit server-minted handles in\\n      tool arguments, not <code>Mcp-Session-Id</code> or connection affinity.\\n      See Chapter 4 for complete JSON-RPC and Streamable HTTP shapes.\\n    </div>\\n  </section>\\n\\n  <div class=\\"hr\\"></div>\\n\\n  <section id=\\"remote-server\\">\\n    <h2 id=\\"6-remote-mcp-servers-and-the-mcp-shop-analogy\\">6) Remote MCP servers and the \u201cmcp.shop\u201d analogy</h2>\\n\\n    <p>\\n      Everything you did above works the same when the server is remote. The only differences are:\\n    </p>\\n    <ul>\\n      <li>The MCP URL becomes something like <code class=\\"inline\\">https://mcp.shop.example/mcp</code></li>\\n      <li>You must add <strong>auth</strong> (almost always)</li>\\n      <li>You should add operational controls: rate limits, logs, monitoring, timeouts</li>\\n    </ul>\\n\\n    <div class=\\"card\\">\\n      <strong>Example \u201cmcp.shop\u201d capabilities</strong>\\n      <ul>\\n        <li><strong>Resources</strong>: <code class=\\"inline\\">shop://catalog</code>, <code class=\\"inline\\">shop://shipping_zones</code>, <code class=\\"inline\\">shop://return_policy</code></li>\\n        <li><strong>Tools</strong>: <code class=\\"inline\\">search_products</code>, <code class=\\"inline\\">inventory_check</code>, <code class=\\"inline\\">create_order</code>, <code class=\\"inline\\">track_order</code></li>\\n        <li><strong>Prompts</strong>: \u201cRecommend products\u201d, \u201cWrite an invoice summary\u201d, \u201cDraft a customer confirmation message\u201d</li>\\n      </ul>\\n    </div>\\n\\n    <div class=\\"callout warn\\">\\n      Remote MCP should be treated like a production API: authentication, authorization, and least-privilege tool exposure\\n      become the main concerns.\\n    </div>\\n  </section>\\n\\n  <section id=\\"openai-llm\\">\\n    <h2 id=\\"7-using-a-remote-mcp-server-from-an-llm-openai-analogy\\">7) Using a remote MCP server from an LLM (OpenAI analogy)</h2>\\n\\n    <p>\\n      You said: \u201cI use OpenAI and my own client with an LLM \u2014 the LLM is actually invoking the server.\u201d\\n      The accurate picture is:\\n    </p>\\n\\n    <div class=\\"card\\">\\n      <div class=\\"diagram\\">\\n        LLM proposes a tool call\\n          \u2193\\n        Your host/client executes the tool call (HTTP request to MCP server)\\n          \u2193\\n        MCP server returns tool result\\n          \u2193\\n        Host/client sends tool result back to the LLM as context\\n      </div>\\n    </div>\\n\\n    <p>\\n      So the LLM isn\u2019t holding sockets or managing auth. Your host is.\\n      The LLM \u201cdecides\u201d which tool to use (within the boundaries you allow).\\n    </p>\\n\\n    <h3 id=\\"conceptual-openai-style-configuration\\">Conceptual OpenAI-style configuration</h3>\\n    <p class=\\"muted\\">\\n      The exact API fields can differ by SDK/version, but the concept is always: configure an MCP tool with a URL, restrict tools, attach headers.\\n    </p>\\n\\n    <pre class=\\"code\\"><code><span class=\\"com\\"># Conceptual OpenAI host wiring for a remote MCP server</span>\\ntools <span class=\\"op\\">=</span> [\\n  {\\n    <span class=\\"str\\">\\"type\\"</span>: <span class=\\"str\\">\\"mcp\\"</span>,\\n    <span class=\\"str\\">\\"server_label\\"</span>: <span class=\\"str\\">\\"mcp.shop\\"</span>,\\n    <span class=\\"str\\">\\"server_url\\"</span>: <span class=\\"str\\">\\"https://mcp.shop.example/mcp\\"</span>,\\n    <span class=\\"str\\">\\"allowed_tools\\"</span>: [<span class=\\"str\\">\\"inventory_check\\"</span>, <span class=\\"str\\">\\"create_order\\"</span>],\\n    <span class=\\"str\\">\\"headers\\"</span>: {<span class=\\"str\\">\\"Authorization\\"</span>: <span class=\\"str\\">\\"Bearer &lt;token&gt;\\"</span>}\\n  }\\n]</code></pre>\\n\\n    <div class=\\"callout ok\\">\\n      <strong>Safety levers you should always use:</strong>\\n      <ul>\\n        <li><strong>allowed_tools</strong>: start minimal (read-only), expand carefully.</li>\\n        <li><strong>server-side authorization</strong>: don\u2019t rely on \u201cthe model will behave\u201d.</li>\\n      </ul>\\n    </div>\\n  </section>\\n\\n  <div class=\\"hr\\"></div>\\n\\n  <section id=\\"auth\\">\\n    <h2 id=\\"8-authentication-and-identity-providers-in-mcp\\">8) Authentication &amp; Identity Providers in MCP</h2>\\n\\n    <p>\\n      MCP runs over HTTP. So authentication looks exactly like a typical API:\\n    </p>\\n    <ul>\\n      <li><strong>Client</strong> obtains an access token from an Identity Provider (IdP)</li>\\n      <li><strong>Client</strong> sends <code class=\\"inline\\">Authorization: Bearer &lt;token&gt;</code> to the MCP server</li>\\n      <li><strong>Server middleware</strong> validates token and attaches identity/scopes to request context</li>\\n      <li><strong>Tools</strong> enforce authorization (scopes/roles) before doing side effects</li>\\n    </ul>\\n\\n    <div class=\\"callout warn\\">\\n      \u201cAuthentication\u201d answers <em>who are you?</em><br>\\n      \u201cAuthorization\u201d answers <em>what are you allowed to do?</em><br>\\n      Middleware usually handles authentication; tool handlers should handle authorization.\\n    </div>\\n  </section>\\n\\n  <section id=\\"auth-selfhosted\\">\\n    <h2 id=\\"9-self-hosted-idp-bearer-token-middleware-validation\\">9) Self-hosted IdP + Bearer token + middleware validation</h2>\\n\\n    <p>\\n      This is the pattern you asked about: \u201cclient gets bearer token from auth server; server validates it.\u201d\\n      We\u2019ll show two validation approaches:\\n    </p>\\n    <ul>\\n      <li><strong>Opaque token</strong> validated by calling IdP introspection endpoint</li>\\n      <li><strong>JWT</strong> validated locally using public keys fetched from IdP (JWKS)</li>\\n    </ul>\\n\\n    <h3 id=\\"9-1-opaque-token-path-introspection\\">9.1 Opaque token path (introspection)</h3>\\n    <div class=\\"card\\">\\n      <div class=\\"diagram\\">\\n        Client \u2192 IdP: standards-based OAuth flow \u2192 access_token (opaque or JWT)<br>\\n        Client \u2192 MCP: Authorization: Bearer access_token<br>\\n        MCP \u2192 IdP: POST /introspect (token) \u2192 active? claims? scopes?<br>\\n        MCP \u2192 allow/deny\\n      </div>\\n    </div>\\n\\n    <h3 id=\\"9-2-server-middleware-example-introspection\\">9.2 Server middleware example (introspection)</h3>\\n    <p class=\\"muted\\">\\n      This middleware sits in front of <code class=\\"inline\\">/mcp</code> and rejects requests without a valid token.\\n    </p>\\n\\n    <pre class=\\"code\\"><code><span class=\\"com\\"># middleware_snippet.py (conceptual)</span>\\nauth <span class=\\"op\\">=</span> request.headers.<span class=\\"fn\\">get</span>(<span class=\\"str\\">\\"authorization\\"</span>, <span class=\\"str\\">\\"\\"</span>)\\n<span class=\\"kw\\">if</span> <span class=\\"kw\\">not</span> auth.<span class=\\"fn\\">startswith</span>(<span class=\\"str\\">\\"Bearer \\"</span>):\\n    <span class=\\"kw\\">return</span> <span class=\\"typ\\">JSONResponse</span>({<span class=\\"str\\">\\"detail\\"</span>: <span class=\\"str\\">\\"Missing Bearer token\\"</span>}, status_code<span class=\\"op\\">=</span><span class=\\"num\\">401</span>)\\n\\ntoken <span class=\\"op\\">=</span> auth.<span class=\\"fn\\">split</span>(<span class=\\"str\\">\\" \\"</span>, <span class=\\"num\\">1</span>)[<span class=\\"num\\">1</span>].<span class=\\"fn\\">strip</span>()\\n\\nr <span class=\\"op\\">=</span> <span class=\\"kw\\">await</span> client.<span class=\\"fn\\">post</span>(\\n    IDP_INTROSPECT_URL,\\n    data<span class=\\"op\\">=</span>{<span class=\\"str\\">\\"token\\"</span>: token},\\n    auth<span class=\\"op\\">=</span>(INTROSPECTION_CLIENT_ID, INTROSPECTION_CLIENT_SECRET),\\n    timeout<span class=\\"op\\">=</span><span class=\\"num\\">5</span>,\\n)\\nr.<span class=\\"fn\\">raise_for_status</span>()\\ndata <span class=\\"op\\">=</span> r.<span class=\\"fn\\">json</span>()\\n<span class=\\"kw\\">if</span> <span class=\\"kw\\">not</span> data.<span class=\\"fn\\">get</span>(<span class=\\"str\\">\\"active\\"</span>):\\n    <span class=\\"kw\\">return</span> <span class=\\"typ\\">JSONResponse</span>({<span class=\\"str\\">\\"detail\\"</span>: <span class=\\"str\\">\\"Invalid token\\"</span>}, status_code<span class=\\"op\\">=</span><span class=\\"num\\">401</span>)\\n\\nrequest.state.sub <span class=\\"op\\">=</span> data.<span class=\\"fn\\">get</span>(<span class=\\"str\\">\\"sub\\"</span>)\\nrequest.state.scope <span class=\\"op\\">=</span> data.<span class=\\"fn\\">get</span>(<span class=\\"str\\">\\"scope\\"</span>, <span class=\\"str\\">\\"\\"</span>)</code></pre>\\n\\n    <div class=\\"callout ok\\">\\n      Once identity is attached to <code class=\\"inline\\">request.state</code>, your tools can enforce permissions:\\n      e.g., <code class=\\"inline\\">order:write</code> required to call <code class=\\"inline\\">create_order</code>.\\n    </div>\\n  </section>\\n\\n  <section id=\\"auth-get-token\\">\\n    <h2 id=\\"10-how-clients-get-tokens-pkce-client-credentials-and-token-exchange\\">10) How clients get tokens: PKCE, client credentials, and token exchange</h2>\\n\\n    <p>\\n      You asked two key questions:\\n    </p>\\n    <ul>\\n      <li>\u201cIn this case we don\u2019t use an auth key just username/password \u2014 can we use an auth key and why?\u201d</li>\\n      <li>\u201cClient has to access Google server to get bearer token still? Is this PKCE?\u201d</li>\\n    </ul>\\n\\n    <h3 id=\\"10-1-confidential-clients-and-services\\">10.1 Confidential clients and services</h3>\\n    <p>\\n      If your client is a backend service, CLI running in a managed environment, or trusted machine workload,\\n      use a standards-based OAuth pattern rather than passing user passwords around:\\n    </p>\\n    <ul>\\n      <li><strong>Authorization Code + PKCE</strong> when a human user is signing in.</li>\\n      <li><strong>Client Credentials</strong> or workload identity federation for service-to-service calls.</li>\\n      <li><strong>Token Exchange</strong> when a host service must call MCP on behalf of an already-authenticated user.</li>\\n    </ul>\\n\\n    <div class=\\"callout\\">\\n      <strong>Where API keys fit:</strong>\\n      API keys can still be useful for legacy integrations, bootstrap, or low-risk service identification,\\n      but they are not the preferred way to represent end-user identity. Prefer OAuth tokens with issuer,\\n      audience, expiry, and scopes.\\n    </div>\\n\\n    <h3 id=\\"10-2-public-clients-cannot-keep-secrets-pkce\\">10.2 Public clients (cannot keep secrets): PKCE</h3>\\n    <p>\\n      In browsers/mobile apps, secrets can be extracted. PKCE exists to secure the authorization code flow for these clients.\\n      The client must talk to the IdP (Google or your IdP) to obtain the token\u2014yes, that\u2019s required.\\n      The server keeping a public key does <em>not</em> remove the need for the client to obtain the token; it only makes server-side validation faster.\\n    </p>\\n\\n    <div class=\\"card\\">\\n      <div class=\\"diagram\\">\\n        Public client (SPA/mobile) gets token from IdP via PKCE<br>\\n        \u2192 then calls MCP server with Authorization: Bearer token\\n      </div>\\n    </div>\\n  </section>\\n\\n  <section id=\\"auth-validate\\">\\n    <h2 id=\\"11-server-validation-introspection-vs-jwks-public-key-retrieval-at-start\\">11) Server validation: introspection vs JWKS (public key retrieval at start)</h2>\\n\\n    <h3 id=\\"11-1-introspection-opaque-tokens\\">11.1 Introspection (opaque tokens)</h3>\\n    <p>\\n      Opaque tokens are validated by calling the IdP (or cached results). This is simple and supports immediate revocation.\\n    </p>\\n\\n    <h3 id=\\"11-2-jwks-jwt-tokens\\">11.2 JWKS (JWT tokens)</h3>\\n    <p>\\n      If your IdP issues JWTs, your MCP server can validate locally. It needs public keys.\\n      The usual pattern is:\\n    </p>\\n    <ol>\\n      <li>On startup, fetch IdP discovery document (or configure JWKS URL directly)</li>\\n      <li>Fetch JWKS and cache keys keyed by <code class=\\"inline\\">kid</code></li>\\n      <li>For each request, read the JWT header.kid and choose key to verify signature</li>\\n      <li>Validate claims: issuer (iss), audience (aud), expiry (exp)</li>\\n      <li>Refresh keys on cache expiration or unknown kid</li>\\n    </ol>\\n\\n    <div class=\\"callout warn\\">\\n      <strong>Answering your earlier question:</strong>\\n      \u201cHow server gets the public key at start?\u201d \u2014 it fetches the JWKS from the IdP and caches it.\\n      It may refresh periodically or when it sees an unknown key id (kid).\\n    </div>\\n  </section>\\n\\n  <section id=\\"best-practices\\">\\n    <span id=\\"troubleshooting\\" class=\\"tr-anchor-target\\" aria-hidden=\\"true\\"></span>\\n    <h2 id=\\"12-best-practices-and-troubleshooting\\">12) Best practices &amp; troubleshooting</h2>\\n\\n    <h3 id=\\"12-1-always-separate-tool-selection-from-tool-execution\\">12.1 Always separate \u201ctool selection\u201d from \u201ctool execution\u201d</h3>\\n    <p>\\n      Let the model suggest which tool to call, but enforce policy in the host:\\n      allowed tool list, argument validation, rate limits, and safe defaults.\\n    </p>\\n\\n    <h3 id=\\"12-2-validate-inputs-server-side\\">12.2 Validate inputs server-side</h3>\\n    <p>\\n      Treat MCP tool calls like API requests. Validate types, lengths, SKU formats, and scope permissions.\\n      Don\u2019t trust that the model will always supply correct values.\\n    </p>\\n\\n    <h3 id=\\"12-3-limit-data-exposure-via-resources\\">12.3 Limit data exposure via resources</h3>\\n    <p>\\n      Just because a resource exists doesn\u2019t mean it should be offered to all callers.\\n      Consider per-user resource filtering (e.g., only their own catalog segment or their own orders).\\n    </p>\\n\\n    <h3 id=\\"12-4-cors-browser-hosts\\">12.4 CORS (browser hosts)</h3>\\n    <p>\\n      If a browser-based host calls your MCP server cross-origin, you must configure CORS properly.\\n      Expect OPTIONS preflight if you use Authorization headers.\\n    </p>\\n    <div class=\\"callout warn\\">\\n      <strong>Industry standard:</strong> do not use wildcard CORS with credentialed requests.\\n      Allow only the exact host origins you operate, return only the methods/headers required,\\n      and keep authorization enforcement on the server even when CORS blocks browsers.\\n    </div>\\n\\n    <div class=\\"callout ok\\">\\n      <strong>One-sentence summary:</strong><br>\\n      MCP defines how capabilities are exposed; your host decides what the model can use; authentication and middleware make remote access safe.\\n    </div>\\n  </section>\\n\\n  <div class=\\"hr\\"></div>\\n\\n  <section>\\n    <h2 id=\\"final-end-to-end-picture\\">Final end-to-end picture</h2>\\n    <div class=\\"card\\">\\n      <div class=\\"diagram\\">\\n        1) Host connects to MCP server and discovers tools/resources/prompts<br>\\n        2) Host obtains bearer token from IdP (PKCE for public clients; client credentials or token exchange for services)<br>\\n        3) Host calls MCP server with Authorization: Bearer token<br>\\n        4) MCP middleware validates token (introspection or JWT+JWKS public key)<br>\\n        5) Host lets model call allow-listed tools; executes calls; returns results to model<br>\\n        6) Tools enforce scopes and perform actions (DB, APIs, etc.)\\n      </div>\\n    </div>\\n  </section>\\n\\n  <section>\\n    <h2 id=\\"official-references\\">Official references</h2>\\n    <ul>\\n      <li><a href=\\"https://modelcontextprotocol.io/specification/2026-07-28\\">MCP <code>2026-07-28</code> specification</a></li>\\n      <li><a href=\\"https://modelcontextprotocol.io/specification/2026-07-28/changelog\\">Key changes from the 2025 protocol family</a></li>\\n      <li><a href=\\"https://modelcontextprotocol.io/specification/2026-07-28/server/discover\\"><code>server/discover</code> reference</a></li>\\n    </ul>\\n  </section>\\n\\n</main>"}'),l={title:"MCP Discovery, Remote Transport, and Authentication",slug:"/part3-agent-protocols/02-mcp-discovery-remote-auth",description:"This chapter connects MCP basics (resources, prompts, tools) to server/client code, how remote MCP servers are used by LLMs (OpenAI-style analogy), and how authentication fits in (self-hosted Identity Provider, Bearer...",sidebar_label:"2. MCP discovery, remote transport, and auth",pagination_label:"2. MCP discovery, remote transport, and auth",hide_title:!0,hide_table_of_contents:!0},c=void 0,p={},d=[];function h(s){return(0,t.jsx)(r.A,{content:i})}function u(s={}){const{wrapper:n}={...(0,o.R)(),...s.components};return n?(0,t.jsx)(n,{...s,children:(0,t.jsx)(h,{...s})}):h()}}}]);